@Test
public void testParserCachingNullKey() throws Exception {
    final LocalClient client = new LocalClient();
    client.setSystemType(FTPClientConfig.SYST_UNIX);
    assertNull(client.getEntryParser());
    client.createParser(null);
    final FTPFileEntryParser entryParser = client.getEntryParser();
    assertNotNull(entryParser);
    client.createParser(null);
    // parser was cached
    assertSame(entryParser, client.getEntryParser());
    client.setSystemType(FTPClientConfig.SYST_NT);
    client.createParser(null);
    // parser was cached
    assertSame(entryParser, client.getEntryParser());
}

@Test
public void testParserCachingWithKey() throws Exception {
    final FTPClient client = new FTPClient();
    assertNull(client.getEntryParser());
    client.createParser(FTPClientConfig.SYST_UNIX);
    final FTPFileEntryParser entryParserSYST = client.getEntryParser();
    assertNotNull(entryParserSYST);
    client.createParser(FTPClientConfig.SYST_UNIX);
    // the previous entry was cached
    assertSame(entryParserSYST, client.getEntryParser());
    client.createParser(FTPClientConfig.SYST_VMS);
    final FTPFileEntryParser entryParserVMS = client.getEntryParser();
    // the previous entry was replaced
    assertNotSame(entryParserSYST, entryParserVMS);
    client.createParser(FTPClientConfig.SYST_VMS);
    // the previous entry was cached
    assertSame(entryParserVMS, client.getEntryParser());
    // revert
    client.createParser(FTPClientConfig.SYST_UNIX);
    // the previous entry was replaced
    assertNotSame(entryParserVMS, client.getEntryParser());
}

@Test
public void testUnparseableFiles() throws Exception {
    final ByteArrayOutputStream baos = new ByteArrayOutputStream();
    baos.write("-rwxr-xr-x   2 root     root         4096 Mar  2 15:13 zxbox".getBytes());
    baos.write(new byte[] { '\r', '\n' });
    baos.write("zrwxr-xr-x   2 root     root         4096 Mar  2 15:13 zxbox".getBytes());
    baos.write(new byte[] { '\r', '\n' });
    final FTPFileEntryParser parser = new UnixFTPEntryParser();
    final FTPClientConfig config = new FTPClientConfig();
    FTPListParseEngine engine = new FTPListParseEngine(parser, config);
    config.setUnparseableEntries(false);
    // use default encoding
    engine.readServerList(new ByteArrayInputStream(baos.toByteArray()), null);
    FTPFile[] files = engine.getFiles();
    assertEquals(1, files.length);
    config.setUnparseableEntries(true);
    engine = new FTPListParseEngine(parser, config);
    // use default encoding
    engine.readServerList(new ByteArrayInputStream(baos.toByteArray()), null);
    files = engine.getFiles();
    assertEquals(2, files.length);
}

@ParameterizedTest
@ValueSource(ints = { FTP.DEFLATE_TRANSFER_MODE })
public void testRetrievingFiles(final int transferMode) throws Exception {
    new File(DEFAULT_HOME).mkdirs();
    final String filename = "test_download.txt";
    final String fileContent = "Created at " + Instant.now();
    Files.write(Paths.get(DEFAULT_HOME).resolve(filename), fileContent.getBytes(StandardCharsets.UTF_8));
    runWithFTPserver((port, user, password) -> {
        final FTPClient client = new FTPClient();
        try {
            client.connect("localhost", port);
            client.login(user, password);
            assertTrue(client.setFileTransferMode(transferMode));
            final FTPFile[] files = client.listFiles();
            assertEquals(1, files.length);
            final ByteArrayOutputStream bos = new ByteArrayOutputStream();
            assertTrue(client.retrieveFile(files[0].getName(), bos));
            assertEquals(fileContent, new String(bos.toByteArray(), StandardCharsets.UTF_8));
        } finally {
            client.logout();
        }
    });
}

@ParameterizedTest
@ValueSource(ints = { FTP.DEFLATE_TRANSFER_MODE })
public void testStoringFiles(final int transferMode) throws Exception {
    runWithFTPserver((port, user, password) -> {
        final FTPClient client = new FTPClient();
        try {
            client.connect("localhost", port);
            client.login(user, password);
            assertTrue(client.setFileTransferMode(transferMode));
            final FTPFile[] filesBeforeUpload = client.listFiles();
            assertEquals(0, filesBeforeUpload.length);
            final String fileName = "test_upload.txt";
            final String fileContent = "Created at " + Instant.now();
            assertTrue(client.storeFile(fileName, new ByteArrayInputStream(fileContent.getBytes(StandardCharsets.UTF_8))));
            final FTPFile[] filesAfterUpload = client.listFiles();
            assertEquals(1, filesAfterUpload.length);
            final Path p = Paths.get(DEFAULT_HOME, fileName);
            assertEquals(fileContent, new String(Files.readAllBytes(p), StandardCharsets.UTF_8));
        } finally {
            client.logout();
        }
    });
}

